def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if rows == 0:
        return grid

    bg_color = grid[0][0]

    min_r, max_r = rows, 0
    min_c, max_c = cols, 0
    frame_color = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                if frame_color is None:
                    frame_color = grid[r][c]
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if frame_color is None or min_r > max_r or min_c > max_c:
        return [row[:] for row in grid]

    corners = {}
    # Identify 4 inner corner values (not frame color, not background)
    tl_pos = (min_r + 1, min_c + 1)
    tr_pos = (min_r + 1, max_c - 1)
    bl_pos = (max_r - 1, min_c + 1)
    br_pos = (max_r - 1, max_c - 1)

    if tl_pos[0] < rows and tl_pos[1] < cols:
        corners['tl'] = grid[tl_pos[0]][tl_pos[1]]
    if tr_pos[0] < rows and tr_pos[1] < cols:
        corners['tr'] = grid[tr_pos[0]][tr_pos[1]]
    if bl_pos[0] < rows and bl_pos[1] < cols:
        corners['bl'] = grid[bl_pos[0]][bl_pos[1]]
    if br_pos[0] < rows and br_pos[1] < cols:
        corners['br'] = grid[br_pos[0]][br_pos[1]]

    output = [row[:] for row in grid]

    # Top/bottom/binside rows, left/right cols
    top_out_r = min_r - 1
    bottom_out_r = max_r + 1
    left_out_c = 0
    right_out_c = max_c + 1

    top_out_r = max(0, min(rows - 1, top_out_r))
    bottom_out_r = max(0, min(rows - 1, bottom_out_r))
    left_out_c = max(0, min(cols - 1, left_out_c))
    right_out_c = max(0, min(cols - 1, right_out_c))

    # 180 degree rotation mapping
    # TL -> BR outside position
    if 'tl' in corners:
        output[bottom_out_r][right_out_c] = corners['tl']
    # TR -> BL outside position
    if 'tr' in corners:
        output[bottom_out_r][left_out_c] = corners['tr']
    # BL -> TR outside position
    if 'bl' in corners:
        output[top_out_r][right_out_c] = corners['bl']
    # BR -> TL outside position
    if 'br' in corners:
        output[top_out_r][left_out_c] = corners['br']

    # Clear inner corners (restore background)
    if tl_pos[0] < rows and tl_pos[1] < cols:
        output[tl_pos[0]][tl_pos[1]] = bg_color
    if tr_pos[0] < rows and tr_pos[1] < cols:
        output[tr_pos[0]][tr_pos[1]] = bg_color
    if bl_pos[0] < rows and bl_pos[1] < cols:
        output[bl_pos[0]][bl_pos[1]] = bg_color
    if br_pos[0] < rows and br_pos[1] < cols:
        output[br_pos[0]][br_pos[1]] = bg_color

    return output

